PRAGMA foreign_keys = ON;

-- BOS_CYO 2026-09-13: complete Dermo Leker Product Master photos from the
-- approved Canva folder. Membership is defined only by the product name
-- containing "leker"; the removed/obsolete Leker category is not consulted.
-- Scope is store_dermo only. All other products and stores are untouched.
-- Canva remains the full-resolution source; D1 embeds optimized 80x80 WebP
-- menu thumbnails in the canonical products.image_data field.
-- DOC-IMPACT: NOT_REQUIRED — store-scoped catalog imagery follows the active
-- Product Master v5 image_data contract; no schema/API/runtime behavior changes.

CREATE TABLE dermo_leker_photo_source_0089 (
  product_name TEXT PRIMARY KEY,
  canva_asset_name TEXT NOT NULL UNIQUE,
  image_data TEXT NOT NULL CHECK (image_data LIKE 'data:image/webp;base64,%')
);











-- Fail closed if the current Dermo name-based Leker set and Canva mapping
-- are not exactly one-to-one. Category and recipe metadata are intentionally
-- excluded from membership.
CREATE TABLE dermo_leker_photo_guard_0089 (ok INTEGER NOT NULL CHECK (ok = 1));
SELECT CASE WHEN
  EXISTS (SELECT 1 FROM stores WHERE id = 'store_dermo')
  AND (SELECT COUNT(*) FROM dermo_leker_photo_source_0089) = 73
  AND (
    SELECT COUNT(*) FROM products
    WHERE store_id = 'store_dermo' AND LOWER(name) LIKE '%leker%'
  ) = 74
  AND (
    SELECT COUNT(*)
    FROM products p
    JOIN dermo_leker_photo_source_0089 s ON s.product_name = p.name
    WHERE p.store_id = 'store_dermo' AND LOWER(p.name) LIKE '%leker%'
  ) = 73
  AND (
    SELECT COUNT(*)
    FROM products p
    WHERE p.store_id = 'store_dermo'
      AND LOWER(p.name) LIKE '%leker%'
      AND NOT EXISTS (
        SELECT 1 FROM dermo_leker_photo_source_0089 s
        WHERE s.product_name = p.name
      )
      AND p.name = 'Adonan Leker'
  ) = 1
THEN 1 ELSE 0 END;
DROP TABLE dermo_leker_photo_guard_0089;

UPDATE products
SET image_data = (
      SELECT s.image_data
      FROM dermo_leker_photo_source_0089 s
      WHERE s.product_name = products.name
    ),
    updated_at = CURRENT_TIMESTAMP
WHERE store_id = 'store_dermo'
  AND LOWER(name) LIKE '%leker%'
  AND EXISTS (
    SELECT 1 FROM dermo_leker_photo_source_0089 s
    WHERE s.product_name = products.name
  );

CREATE TABLE dermo_leker_photo_verify_0089 (ok INTEGER NOT NULL CHECK (ok = 1));
SELECT CASE WHEN (
  SELECT COUNT(*)
  FROM products p
  JOIN dermo_leker_photo_source_0089 s
    ON s.product_name = p.name AND s.image_data = p.image_data
  WHERE p.store_id = 'store_dermo' AND LOWER(p.name) LIKE '%leker%'
) = 73 THEN 1 ELSE 0 END;
DROP TABLE dermo_leker_photo_verify_0089;
DROP TABLE dermo_leker_photo_source_0089;
